import os, glob

candidates = [
    "/mlx_devbox/users/zhengxinran/playground/code_zxr/agent_safety/benchmarks/external/MSB/.venv/lib",
    "/home/tiger/miniconda3/lib",
    "/home/tiger/.local/lib",
    "/usr/lib/python3",
    "/usr/local/lib",
]

targets = ["pypdf", "PyPDF2", "reportlab", "pdfplumber", "fitz", "pypdfium2", "fpdf"]

seen = set()
for base in candidates:
    if not os.path.isdir(base):
        continue
    for sp in glob.glob(os.path.join(base, "python3*", "site-packages")) + glob.glob(os.path.join(base, "python3*", "dist-packages")):
        if sp in seen:
            continue
        seen.add(sp)
        found = []
        for t in targets:
            if os.path.isdir(os.path.join(sp, t)) or os.path.isfile(os.path.join(sp, t + ".py")):
                found.append(t)
        if found:
            print(sp, "->", found)
print("scan done; dirs scanned:", len(seen))

